<style>
  /* Default: kleine Phones (<= 390px) */
  .fc-custom-pos {
    position: fixed;           /* Safety */
    right: 16px !important;
    bottom: 16px !important;
    z-index: 2147483000 !important; /* über Cookie-Bannern etc. */
  }

  /* 391–810px (Tablet/ große Phones) */
  @media (min-width: 391px) and (max-width: 810px) {
    .fc-custom-pos {
      right: 16px !important;
      bottom: 16px !important;
    }
  }

  /* 811–1199px (Tablet quer / kleines Desktop) */
  @media (min-width: 811px) and (max-width: 1199px) {
    .fc-custom-pos {
      right: 24px !important;
      bottom: 16px !important;
    }
  }

  /* >=1200px (Desktop) */
  @media (min-width: 1200px) {
    .fc-custom-pos {
      right: 24px !important;
      bottom: 16px !important;
    }
  }
</style>

